std::optional<AgentEvent> poll_until(OpenAIResponsesAgent& agent, AgentEventKind kind)
{
    for (int i = 0; i < 20; ++i) {
        auto event = agent.poll();
        if (event && event->kind == kind)
            return event;
    }
    return std::nullopt;
}

